bool ObstacleStop::modify_trajectory(TrajectoryPoints & traj_points)
{
  autoware_utils_debug::ScopedTimeTrack st("ObstacleStop::modify_trajectory", *get_time_keeper());

  if (!enabled_) return false;

  auto trajectory = traj_points;
  utils::obstacle_stop::trim_trajectory_and_remove_duplicates(trajectory);
  if (trajectory.empty()) return false;

  if (!is_trajectory_modification_required(trajectory)) return false;

  if (!nearest_collision_point_) return false;

  traj_points = std::move(trajectory);

  return set_stop_point(traj_points);
}

void trim_trajectory_and_remove_duplicates(TrajectoryPoints & trajectory_points)
{
  if (trajectory_points.empty()) return;
  const auto zero_velocity_index =
    autoware::motion_utils::searchZeroVelocityIndex(trajectory_points);
  if (zero_velocity_index && zero_velocity_index.value() < trajectory_points.size() - 1) {
    trajectory_points.erase(
      trajectory_points.begin() + zero_velocity_index.value() + 1, trajectory_points.end());
  }
  trajectory_points = autoware::motion_utils::removeOverlapPoints(trajectory_points);
}

[[nodiscard]] std::optional<size_t> searchZeroVelocityIndex(const T & points_with_twist)
{
  return searchZeroVelocityIndex(points_with_twist, 0, points_with_twist.size());
}

[[nodiscard]] std::optional<size_t> searchZeroVelocityIndex(
  const T & points_with_twist, const size_t src_idx, const size_t dst_idx)
{
  try {
    validateNonEmpty(points_with_twist);
  } catch (const std::exception & e) {
    RCLCPP_DEBUG(get_logger(), "%s", e.what());
    return {};
  }

  constexpr double epsilon = 1e-3;
  for (size_t i = src_idx; i < dst_idx; ++i) {
    if (std::fabs(points_with_twist.at(i).longitudinal_velocity_mps) < epsilon) {
      return i;
    }
  }

  return {};
}

[[nodiscard]] T removeOverlapPoints(const T & points, const size_t start_idx = 0)
{
  if (points.size() < start_idx + 1) {
    return points;
  }

  T dst;
  dst.reserve(points.size());

  for (size_t i = 0; i <= start_idx; ++i) {
    dst.push_back(points.at(i));
  }

  constexpr double eps = 1.0E-08;
  for (size_t i = start_idx + 1; i < points.size(); ++i) {
    const auto prev_p = autoware_utils_geometry::get_point(dst.back());
    const auto curr_p = autoware_utils_geometry::get_point(points.at(i));
    if (std::abs(prev_p.x - curr_p.x) < eps && std::abs(prev_p.y - curr_p.y) < eps) {
      continue;
    }
    dst.push_back(points.at(i));
  }

  return dst;
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

bool ObstacleStop::is_trajectory_modification_required(const TrajectoryPoints & traj_points)
{
  debug_data_ = DebugData();
  safety_factors_ = SafetyFactorArray{};

  if (traj_points.empty()) {
    nearest_collision_point_ = std::nullopt;
    return false;
  }

  {
    autoware_utils_debug::ScopedTimeTrack st(
      "ObstacleStop::get_trajectory_shape", *get_time_keeper());

    debug_data_.trajectory_shape = get_trajectory_shape(
      traj_points, data_->current_odometry->pose.pose, data_->vehicle_info,
      data_->current_odometry->twist.twist.linear.x,
      data_->current_acceleration->accel.accel.linear.x, params_.nominal_stopping_decel,
      params_.stopping_jerk, params_.stop_margin, params_.lateral_margin);
  }

  check_obstacles(traj_points);

  debug_data_.active_collision_point =
    nearest_collision_point_ ? nearest_collision_point_->point : geometry_msgs::msg::Point();

  return nearest_collision_point_ != std::nullopt;
}

TrajectoryShape get_trajectory_shape(
  const TrajectoryPoints & trajectory_points, const geometry_msgs::msg::Pose & ego_pose,
  const autoware::vehicle_info_utils::VehicleInfo & vehicle_info, const double ego_vel,
  const double ego_accel, const double decel, const double jerk, const double stop_margin,
  const double lateral_margin, const double longitudinal_margin)
{
  const auto offset_pose =
    autoware_utils::calc_offset_pose(ego_pose, vehicle_info.max_longitudinal_offset_m, 0, 0);
  auto start_idx = motion_utils::findNearestSegmentIndex(trajectory_points, offset_pose.position);

  const auto traj_length = motion_utils::calcArcLength(trajectory_points);
  const auto ego_arc_length =
    motion_utils::calcSignedArcLength(trajectory_points, 0, ego_pose.position);
  const auto forward_traj_length = traj_length - ego_arc_length;

  const auto detection_length =
    get_detection_length(forward_traj_length, ego_vel, ego_accel, decel, jerk, stop_margin);

  const auto detection_traj = std::invoke([&]() -> TrajectoryPoints {
    if (detection_length < forward_traj_length) {
      return motion_utils::cropForwardPoints(
        trajectory_points, ego_pose.position, start_idx, detection_length);
    }
    return extend_trajectory(trajectory_points, stop_margin, vehicle_info.wheel_base_m);
  });

  autoware_utils_geometry::LineString2d ls_front_right;
  autoware_utils_geometry::LineString2d ls_front_left;
  autoware_utils_geometry::LineString2d ls_rear_right;
  autoware_utils_geometry::LineString2d ls_rear_left;
  ls_front_right.reserve(detection_traj.size());
  ls_front_left.reserve(detection_traj.size());
  ls_rear_right.reserve(detection_traj.size());
  ls_rear_left.reserve(detection_traj.size());

  autoware_utils_geometry::Polygon2d polygon_front;
  autoware_utils_geometry::Polygon2d polygon_rear;

  constexpr double min_resolution = 0.1;

  const auto base_footprint = vehicle_info.createFootprint(lateral_margin, longitudinal_margin);
  for (const auto & [idx, p] : detection_traj | ranges::views::enumerate) {
    if (idx > 0) {
      const auto & prev_p = detection_traj[idx - 1];
      const auto dist = autoware_utils::calc_distance2d(prev_p, p);
      if (dist < min_resolution) continue;
    }
    const autoware_utils_geometry::Point2d base_link(p.pose.position.x, p.pose.position.y);
    const auto angle = tf2::getYaw(p.pose.orientation);
    const Eigen::Rotation2Dd rotation(angle);
    const auto front_left_offset =
      rotation * base_footprint[vehicle_info_utils::VehicleInfo::FrontLeftIndex];
    const auto front_right_offset =
      rotation * base_footprint[vehicle_info_utils::VehicleInfo::FrontRightIndex];
    const auto rear_right_offset =
      rotation * base_footprint[vehicle_info_utils::VehicleInfo::RearRightIndex];
    const auto rear_left_offset =
      rotation * base_footprint[vehicle_info_utils::VehicleInfo::RearLeftIndex];
    ls_front_left.emplace_back(
      base_link.x() + front_left_offset.x(), base_link.y() + front_left_offset.y());
    ls_front_right.emplace_back(
      base_link.x() + front_right_offset.x(), base_link.y() + front_right_offset.y());
    ls_rear_right.emplace_back(
      base_link.x() + rear_right_offset.x(), base_link.y() + rear_right_offset.y());
    ls_rear_left.emplace_back(
      base_link.x() + rear_left_offset.x(), base_link.y() + rear_left_offset.y());
  }
  ls_rear_left.emplace_back(ls_front_left.back());
  ls_rear_right.emplace_back(ls_front_right.back());
  ls_front_left.insert(ls_front_left.begin(), ls_rear_left.front());
  ls_front_right.insert(ls_front_right.begin(), ls_rear_right.front());

  boost::geometry::reverse(ls_front_right);
  boost::geometry::reverse(ls_rear_right);

  boost::geometry::append(polygon_front, ls_front_left);
  boost::geometry::append(polygon_front, ls_front_right);
  boost::geometry::append(polygon_rear, ls_rear_left);
  boost::geometry::append(polygon_rear, ls_rear_right);

  boost::geometry::correct(polygon_front);
  boost::geometry::correct(polygon_rear);

  autoware_utils_geometry::MultiPolygon2d trajectory_polygon;
  boost::geometry::union_(polygon_front, polygon_rear, trajectory_polygon);

  autoware_utils_geometry::Box2d envelope;
  boost::geometry::envelope(trajectory_polygon, envelope);

  return TrajectoryShape{trajectory_polygon, envelope, traj_length, forward_traj_length};
}

double get_detection_length(
  const double forward_traj_length, const double current_vel, const double current_accel,
  const double decel, const double jerk, const double stop_margin)
{
  // add a buffer length to account for the reaction time of the vehicle
  constexpr double buffer_length = 1.0;
  const auto margin = stop_margin + buffer_length;
  auto nominal_stopping_distance =
    autoware::motion_utils::calculate_stop_distance(current_vel, current_accel, decel, jerk, 0.0);
  if (nominal_stopping_distance) {
    return nominal_stopping_distance.value() + margin;
  }
  return forward_traj_length + margin;
}

[[nodiscard]] std::optional<double> calculate_stop_distance(
  const double v0, const double a0, const double decel_limit, const double jerk_limit,
  const double initial_time_delay)
{
  // already stopped or reversing
  if (v0 <= 0.0) {
    return 0.0;
  }

  // jerk and acceleration limits must be strictly negative to stop a forward-moving vehicle.
  const auto negative_jerk_limit = -std::abs(jerk_limit);
  // ensure current_acc respects the deceleration limit, otherwise the maths break down
  const auto negative_decel_limit = std::min(-std::abs(decel_limit), a0);
  // using epsilon to prevent division by zero.
  if (negative_jerk_limit >= -epsilon || negative_decel_limit >= -epsilon) {
    return std::nullopt;
  }

  // Phase 1: latency delay
  const double t1 = std::max(0.0, initial_time_delay);
  const auto [x1, v1, a1] = update(0.0, v0, a0, 0.0, t1);

  // If the vehicle naturally stops during the delay phase due to existing deceleration
  if (v1 <= 0.0 && (a0 <= -epsilon || a0 >= epsilon)) {
    const double t_stop = -v0 / a0;
    const auto [x_stop, v_stop, a_stop] = update(0.0, v0, a0, 0.0, t_stop);
    return std::max(0.0, x_stop);
  }

  // Phase 2: jerk-limited braking
  // Calculate what the velocity (v2) would be exactly when the acceleration reaches acc_limit
  const double v2 =
    v1 + (negative_decel_limit * negative_decel_limit - a1 * a1) / (2.0 * negative_jerk_limit);

  if (v2 <= 0.0) {
    // The vehicle reaches v = 0 before hitting the maximum deceleration limit.
    // Solve for t where 0 = v1 + a1*t + 0.5*j*t^2
    const double discriminant = a1 * a1 - 2.0 * negative_jerk_limit * v1;

    // should be impossible
    if (discriminant < 0.0) {
      return std::nullopt;
    }

    const double t2 = std::max(0.0, -(a1 + std::sqrt(discriminant)) / negative_jerk_limit);
    const auto [x_stop, v_stop, a_stop] = update(x1, v1, a1, negative_jerk_limit, t2);

    return std::max(0.0, x_stop);
  }

  // The vehicle successfully reaches the maximum deceleration limit.
  const double t2 = std::max(0.0, (negative_decel_limit - a1) / negative_jerk_limit);
  const auto [x2, v2_final, a2_final] = update(x1, v1, a1, negative_jerk_limit, t2);

  // Phase 3: Constant maximum deceleration
  // Decelerate at acc_limit from v2_final down to 0.
  const double x3 = -(v2_final * v2_final) / (2.0 * negative_decel_limit);

  return std::max(0.0, x2 + x3);
}

std::tuple<double, double, double> update(
  const double x, const double v, const double a, const double j, const double t)
{
  const double a_new = a + j * t;
  const double v_new = v + a * t + 0.5 * j * t * t;
  const double x_new = x + v * t + 0.5 * a * t * t + (1.0 / 6.0) * j * t * t * t;

  return {x_new, v_new, a_new};
}

std::tuple<double, double, double> update(
  const double x, const double v, const double a, const double j, const double t)
{
  const double a_new = a + j * t;
  const double v_new = v + a * t + 0.5 * j * t * t;
  const double x_new = x + v * t + 0.5 * a * t * t + (1.0 / 6.0) * j * t * t * t;

  return {x_new, v_new, a_new};
}

std::tuple<double, double, double> update(
  const double x, const double v, const double a, const double j, const double t)
{
  const double a_new = a + j * t;
  const double v_new = v + a * t + 0.5 * j * t * t;
  const double x_new = x + v * t + 0.5 * a * t * t + (1.0 / 6.0) * j * t * t * t;

  return {x_new, v_new, a_new};
}

T cropForwardPoints(
  const T & points, const geometry_msgs::msg::Point & target_pos, const size_t target_seg_idx,
  const double forward_length)
{
  if (points.empty()) {
    return T{};
  }

  double sum_length =
    -autoware::motion_utils::calcLongitudinalOffsetToSegment(points, target_seg_idx, target_pos);
  for (size_t i = target_seg_idx + 1; i < points.size(); ++i) {
    sum_length += autoware_utils_geometry::calc_distance2d(points.at(i), points.at(i - 1));
    if (forward_length < sum_length) {
      const size_t end_idx = i;
      return T{points.begin(), points.begin() + end_idx};
    }
  }

  return points;
}

double calcLongitudinalOffsetToSegment(
  const T & points, const size_t seg_idx, const geometry_msgs::msg::Point & p_target,
  const bool throw_exception = false)
{
  if (seg_idx >= points.size() - 1) {
    const std::string error_message(
      "[autoware_motion_utils] " + std::string(__func__) +
      ": Failed to calculate longitudinal offset because the given segment index is out of the "
      "points size.");
    autoware_utils_system::print_backtrace();
    if (throw_exception) {
      throw std::out_of_range(error_message);
    }
    RCLCPP_DEBUG(
      get_logger(),
      "%s Return NaN since no_throw option is enabled. The maintainer must check the code.",
      error_message.c_str());
    return std::nan("");
  }

  const auto overlap_removed_points = removeOverlapPoints(points, seg_idx);

  if (throw_exception) {
    validateNonEmpty(overlap_removed_points);
  } else {
    try {
      validateNonEmpty(overlap_removed_points);
    } catch (const std::exception & e) {
      RCLCPP_DEBUG(get_logger(), "%s", e.what());
      return std::nan("");
    }
  }

  if (seg_idx >= overlap_removed_points.size() - 1) {
    const std::string error_message(
      "[autoware_motion_utils] " + std::string(__func__) +
      ": Longitudinal offset calculation is not supported for the same points.");
    autoware_utils_system::print_backtrace();
    if (throw_exception) {
      throw std::runtime_error(error_message);
    }
    RCLCPP_DEBUG(
      get_logger(),
      "%s Return NaN since no_throw option is enabled. The maintainer must check the code.",
      error_message.c_str());
    return std::nan("");
  }

  const auto p_front = autoware_utils_geometry::get_point(overlap_removed_points.at(seg_idx));
  const auto p_back = autoware_utils_geometry::get_point(overlap_removed_points.at(seg_idx + 1));

  const Eigen::Vector3d segment_vec{p_back.x - p_front.x, p_back.y - p_front.y, 0};
  const Eigen::Vector3d target_vec{p_target.x - p_front.x, p_target.y - p_front.y, 0};

  return segment_vec.dot(target_vec) / segment_vec.norm();
}

[[nodiscard]] T removeOverlapPoints(const T & points, const size_t start_idx = 0)
{
  if (points.size() < start_idx + 1) {
    return points;
  }

  T dst;
  dst.reserve(points.size());

  for (size_t i = 0; i <= start_idx; ++i) {
    dst.push_back(points.at(i));
  }

  constexpr double eps = 1.0E-08;
  for (size_t i = start_idx + 1; i < points.size(); ++i) {
    const auto prev_p = autoware_utils_geometry::get_point(dst.back());
    const auto curr_p = autoware_utils_geometry::get_point(points.at(i));
    if (std::abs(prev_p.x - curr_p.x) < eps && std::abs(prev_p.y - curr_p.y) < eps) {
      continue;
    }
    dst.push_back(points.at(i));
  }

  return dst;
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

double calc_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  return std::hypot(p1.x - p2.x, p1.y - p2.y);
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

TrajectoryPoints extend_trajectory(
  const TrajectoryPoints & trajectory_points, const double length, const double wheelbase_length)
{
  if (length < 1e-3 || trajectory_points.empty()) return trajectory_points;

  const auto & last_p = trajectory_points.back();
  const auto yaw_last = tf2::getYaw(last_p.pose.orientation);
  constexpr double lookback_distance = 1.0;  // [m]
  const auto lookback_pose = motion_utils::calcLongitudinalOffsetPose(
    trajectory_points, trajectory_points.size() - 1, -1.0 * lookback_distance);

  auto steering_angle = 0.0;
  if (lookback_pose) {
    const auto lookback_yaw = tf2::getYaw(lookback_pose.value().orientation);
    const auto delta_yaw = autoware_utils_geometry::normalize_radian(yaw_last - lookback_yaw);
    const auto k = delta_yaw / lookback_distance;
    steering_angle = std::atan(k * wheelbase_length);
  }

  if (std::abs(steering_angle) < 1e-3) {
    auto extended_trajectory = trajectory_points;
    auto p = trajectory_points.back();
    p.pose = autoware_utils::calc_offset_pose(p.pose, length, 0, 0);
    extended_trajectory.push_back(p);
    return extended_trajectory;
  }

  const auto turn_radius = wheelbase_length / std::tan(steering_angle);
  const auto yaw = tf2::getYaw(last_p.pose.orientation);

  constexpr double step = 0.5;
  TrajectoryPoints extended_trajectory;
  for (auto d = length; d > 0; d -= step) {
    auto p = last_p;
    const auto beta = d / turn_radius;
    p.pose.position.x += turn_radius * (std::sin(yaw + beta) - std::sin(yaw));
    p.pose.position.y += turn_radius * (std::cos(yaw) - std::cos(yaw + beta));
    p.pose.orientation = autoware_utils::create_quaternion_from_yaw(yaw + beta);
    extended_trajectory.push_back(p);
  }
  std::reverse(extended_trajectory.begin(), extended_trajectory.end());

  extended_trajectory.insert(
    extended_trajectory.begin(), trajectory_points.begin(), trajectory_points.end());
  return extended_trajectory;
}

std::optional<geometry_msgs::msg::Pose> calcLongitudinalOffsetPose(
  const T & points, const size_t src_idx, const double offset,
  const bool set_orientation_from_position_direction = true, const bool throw_exception = false)
{
  try {
    validateNonEmpty(points);
  } catch (const std::exception & e) {
    RCLCPP_DEBUG(get_logger(), "Failed to calculate longitudinal offset: %s", e.what());
    return {};
  }

  if (points.size() - 1 < src_idx) {
    const std::string error_message(
      "[autoware_motion_utils] " + std::string(__func__) +
      " error: The given source index is out of the points size. Failed to calculate longitudinal "
      "offset.");
    autoware_utils_system::print_backtrace();
    if (throw_exception) {
      throw std::out_of_range(error_message);
    }
    RCLCPP_DEBUG(get_logger(), "%s", error_message.c_str());
    return {};
  }

  if (points.size() == 1) {
    RCLCPP_DEBUG(get_logger(), "Failed to calculate longitudinal offset: points size is one.");
    return {};
  }

  if (src_idx + 1 == points.size() && offset == 0.0) {
    return autoware_utils_geometry::get_pose(points.at(src_idx));
  }

  if (offset < 0.0) {
    auto reverse_points = points;
    std::reverse(reverse_points.begin(), reverse_points.end());

    double dist_sum = 0.0;

    for (size_t i = reverse_points.size() - src_idx - 1; i < reverse_points.size() - 1; ++i) {
      const auto & p_front = reverse_points.at(i);
      const auto & p_back = reverse_points.at(i + 1);

      const auto dist_segment = autoware_utils_geometry::calc_distance2d(p_front, p_back);
      dist_sum += dist_segment;

      const auto dist_res = -offset - dist_sum;
      if (dist_res <= 0.0) {
        return autoware_utils_geometry::calc_interpolated_pose(
          p_back, p_front, std::abs(dist_res / dist_segment),
          set_orientation_from_position_direction);
      }
    }
  } else {
    double dist_sum = 0.0;

    for (size_t i = src_idx; i < points.size() - 1; ++i) {
      const auto & p_front = points.at(i);
      const auto & p_back = points.at(i + 1);

      const auto dist_segment = autoware_utils_geometry::calc_distance2d(p_front, p_back);
      dist_sum += dist_segment;

      const auto dist_res = offset - dist_sum;
      if (dist_res <= 0.0) {
        return autoware_utils_geometry::calc_interpolated_pose(
          p_front, p_back, 1.0 - std::abs(dist_res / dist_segment),
          set_orientation_from_position_direction);
      }
    }
  }

  // not found (out of range)
  return {};
}

geometry_msgs::msg::Pose get_pose([[maybe_unused]] const T & p)
{
  static_assert(sizeof(T) == 0, "Only specializations of get_pose can be used.");
  throw std::logic_error("Only specializations of get_pose can be used.");
}

double calc_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  return std::hypot(p1.x - p2.x, p1.y - p2.y);
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

geometry_msgs::msg::Pose calc_interpolated_pose(
  const Pose1 & src_pose, const Pose2 & dst_pose, const double ratio,
  const bool set_orientation_from_position_direction = true)
{
  const double clamped_ratio = std::clamp(ratio, 0.0, 1.0);

  geometry_msgs::msg::Pose output_pose;
  output_pose.position =
    calc_interpolated_point(get_point(src_pose), get_point(dst_pose), clamped_ratio);

  if (set_orientation_from_position_direction) {
    const double input_poses_dist = calc_distance2d(get_point(src_pose), get_point(dst_pose));
    const bool is_driving_forward_flag = is_driving_forward(src_pose, dst_pose);

    // Get orientation from interpolated point and src_pose
    if ((is_driving_forward_flag && clamped_ratio > 1.0 - (1e-6)) || input_poses_dist < 1e-3) {
      output_pose.orientation = get_pose(dst_pose).orientation;
    } else if (!is_driving_forward_flag && clamped_ratio < 1e-6) {
      output_pose.orientation = get_pose(src_pose).orientation;
    } else {
      const auto & base_pose = is_driving_forward_flag ? dst_pose : src_pose;
      const double pitch = calc_elevation_angle(get_point(output_pose), get_point(base_pose));
      const double yaw = calc_azimuth_angle(get_point(output_pose), get_point(base_pose));
      output_pose.orientation = create_quaternion_from_rpy(0.0, pitch, yaw);
    }
  } else {
    // Get orientation by spherical linear interpolation
    tf2::Transform src_tf;
    tf2::Transform dst_tf;
    tf2::fromMsg(get_pose(src_pose), src_tf);
    tf2::fromMsg(get_pose(dst_pose), dst_tf);
    const auto & quaternion = tf2::slerp(src_tf.getRotation(), dst_tf.getRotation(), clamped_ratio);
    output_pose.orientation = tf2::toMsg(quaternion);
  }

  return output_pose;
}

geometry_msgs::msg::Point calc_interpolated_point(
  const Point1 & src, const Point2 & dst, const double ratio)
{
  const auto src_point = get_point(src);
  const auto dst_point = get_point(dst);

  tf2::Vector3 src_vec;
  src_vec.setX(src_point.x);
  src_vec.setY(src_point.y);
  src_vec.setZ(src_point.z);

  tf2::Vector3 dst_vec;
  dst_vec.setX(dst_point.x);
  dst_vec.setY(dst_point.y);
  dst_vec.setZ(dst_point.z);

  // Get pose by linear interpolation
  const double clamped_ratio = std::clamp(ratio, 0.0, 1.0);
  const auto & vec = tf2::lerp(src_vec, dst_vec, clamped_ratio);

  geometry_msgs::msg::Point point;
  point.x = vec.x();
  point.y = vec.y();
  point.z = vec.z();

  return point;
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

bool is_driving_forward(const Pose1 & src_pose, const Pose2 & dst_pose)
{
  // check the first point direction
  const double src_yaw = tf2::getYaw(get_pose(src_pose).orientation);
  const double pose_direction_yaw = calc_azimuth_angle(get_point(src_pose), get_point(dst_pose));
  return std::fabs(normalize_radian(src_yaw - pose_direction_yaw)) < pi / 2.0;
}

double calc_azimuth_angle(
  const geometry_msgs::msg::Point & p_from, const geometry_msgs::msg::Point & p_to)
{
  const double dx = p_to.x - p_from.x;
  const double dy = p_to.y - p_from.y;
  return std::atan2(dy, dx);
}

inline double normalize_radian(const double rad, const double min_rad = -pi)
{
  const auto max_rad = min_rad + 2 * pi;

  const auto value = std::fmod(rad, 2 * pi);
  if (min_rad <= value && value < max_rad) {
    return value;
  }

  return value - std::copysign(2 * pi, value);
}

geometry_msgs::msg::Quaternion create_quaternion_from_rpy(
  const double roll, const double pitch, const double yaw)
{
  tf2::Quaternion q;
  q.setRPY(roll, pitch, yaw);
  return tf2::toMsg(q);
}

inline double normalize_radian(const double rad, const double min_rad = -pi)
{
  const auto max_rad = min_rad + 2 * pi;

  const auto value = std::fmod(rad, 2 * pi);
  if (min_rad <= value && value < max_rad) {
    return value;
  }

  return value - std::copysign(2 * pi, value);
}

geometry_msgs::msg::Pose calc_offset_pose(
  const geometry_msgs::msg::Pose & p, const double x, const double y, const double z,
  const double yaw)
{
  geometry_msgs::msg::Pose pose;
  geometry_msgs::msg::Transform transform;
  transform.translation = create_translation(x, y, z);
  transform.rotation = create_quaternion_from_yaw(yaw);
  tf2::Transform tf_pose;
  tf2::Transform tf_offset;
  tf2::fromMsg(transform, tf_offset);
  tf2::fromMsg(p, tf_pose);
  tf2::toMsg(tf_pose * tf_offset, pose);
  return pose;
}

geometry_msgs::msg::Vector3 create_translation(const double x, const double y, const double z)
{
  geometry_msgs::msg::Vector3 v;
  v.x = x;
  v.y = y;
  v.z = z;
  return v;
}

geometry_msgs::msg::Quaternion create_quaternion_from_yaw(const double yaw)
{
  tf2::Quaternion q;
  q.setRPY(0, 0, yaw);
  return tf2::toMsg(q);
}

geometry_msgs::msg::Quaternion create_quaternion_from_yaw(const double yaw)
{
  tf2::Quaternion q;
  q.setRPY(0, 0, yaw);
  return tf2::toMsg(q);
}

autoware_utils_geometry::LinearRing2d VehicleInfo::createFootprint(
  const double lat_margin, const double lon_margin) const
{
  return createFootprint(lat_margin, lat_margin, lat_margin, lon_margin, lon_margin);
}

autoware_utils_geometry::LinearRing2d VehicleInfo::createFootprint(
  const double front_lat_margin, const double center_lat_margin, const double rear_lat_margin,
  const double front_lon_margin, const double rear_lon_margin, const bool center_at_base_link) const
{
  using autoware_utils_geometry::LinearRing2d;
  using autoware_utils_geometry::Point2d;

  // Longitudinal positions
  const double x_front = front_overhang_m + wheel_base_m + front_lon_margin;
  const double x_center = center_at_base_link ? 0.0 : (wheel_base_m / 2.0);
  const double x_rear = -(rear_overhang_m + rear_lon_margin);

  const double y_left_front = wheel_tread_m * 0.5 + left_overhang_m + front_lat_margin;
  const double y_right_front = -(wheel_tread_m * 0.5 + right_overhang_m + front_lat_margin);

  const double y_left_center = wheel_tread_m * 0.5 + left_overhang_m + center_lat_margin;
  const double y_right_center = -(wheel_tread_m * 0.5 + right_overhang_m + center_lat_margin);

  const double y_left_rear = wheel_tread_m * 0.5 + left_overhang_m + rear_lat_margin;
  const double y_right_rear = -(wheel_tread_m * 0.5 + right_overhang_m + rear_lat_margin);

  LinearRing2d footprint;
  footprint.reserve(7);
  footprint.emplace_back(x_front, y_left_front);
  footprint.emplace_back(x_front, y_right_front);
  footprint.emplace_back(x_center, y_right_center);
  footprint.emplace_back(x_rear, y_right_rear);
  footprint.emplace_back(x_rear, y_left_rear);
  footprint.emplace_back(x_center, y_left_center);
  footprint.emplace_back(x_front, y_left_front);

  return footprint;
}

void ObstacleStop::check_obstacles(const TrajectoryPoints & traj_points)
{
  autoware_utils_debug::ScopedTimeTrack st("ObstacleStop::check_obstacles", *get_time_keeper());
  const auto collision_point_objects = check_predicted_objects(traj_points);
  const auto collision_point_pcd = check_pointcloud(traj_points);

  auto get_safety_factor = [&](
                             const geometry_msgs::msg::Point & point,
                             const SafetyFactor::_type_type type) -> SafetyFactor {
    SafetyFactor safety_factor;
    safety_factor.type = type;
    safety_factor.points.emplace_back(point);
    safety_factor.is_safe = false;
    return safety_factor;
  };

  if (collision_point_objects) {
    RCLCPP_WARN_THROTTLE(
      get_node_ptr()->get_logger(), *get_clock(), 1000,
      "[TM ObstacleStop] Detected collision with object at arc length %f m",
      collision_point_objects->arc_length);
    if (debug_data_.colliding_object) {
      auto safety_factor = get_safety_factor(
        debug_data_.colliding_object->kinematics.initial_pose_with_covariance.pose.position,
        SafetyFactor::OBJECT);
      safety_factor.object_id = debug_data_.colliding_object->object_id;
      safety_factors_.factors.push_back(safety_factor);
    }
  }

  if (collision_point_pcd) {
    RCLCPP_WARN_THROTTLE(
      get_node_ptr()->get_logger(), *get_clock(), 1000,
      "[TM ObstacleStop] Detected collision with pointcloud at arc length %f m",
      collision_point_pcd->arc_length);
    auto safety_factor = get_safety_factor(collision_point_pcd->point, SafetyFactor::POINTCLOUD);
    safety_factors_.factors.push_back(safety_factor);
  }

  nearest_collision_point_ = std::invoke([&]() -> std::optional<CollisionPoint> {
    const auto is_collision_point_pcd = params_.enable_stop_for_pointcloud && collision_point_pcd;
    const auto is_collision_point_objects =
      params_.enable_stop_for_objects && collision_point_objects;
    if (!is_collision_point_pcd && !is_collision_point_objects) return std::nullopt;
    if (!is_collision_point_pcd) return collision_point_objects.value();
    if (!is_collision_point_objects) return collision_point_pcd.value();
    return collision_point_pcd->arc_length < collision_point_objects->arc_length
             ? collision_point_pcd.value()
             : collision_point_objects.value();
  });
}

std::optional<CollisionPoint> ObstacleStop::check_predicted_objects(
  const TrajectoryPoints & traj_points)
{
  autoware_utils_debug::ScopedTimeTrack st(
    "ObstacleStop::check_predicted_objects", *get_time_keeper());
  if (
    !params_.use_objects || !data_->predicted_objects || data_->predicted_objects->objects.empty())
    return std::nullopt;
  auto predicted_objects = *data_->predicted_objects;

  object_filter_->filter_objects(predicted_objects);

  PredictedObjects active_objects;
  obstacle_tracker_->update_objects(predicted_objects, active_objects, get_clock()->now());

  autoware_perception_msgs::msg::PredictedObject colliding_object;
  auto collision_point = std::invoke([&]() -> std::optional<CollisionPoint> {
    if (!params_.rss_params.enable) {
      return get_nearest_object_collision(
        traj_points, debug_data_.trajectory_shape, active_objects, debug_data_.target_polygons,
        colliding_object);
    }
    return get_nearest_object_collision(
      traj_points, debug_data_.trajectory_shape, data_->vehicle_info, active_objects,
      object_decel_map_, data_->current_odometry->twist.twist.linear.x,
      params_.nominal_stopping_decel, params_.rss_params.reaction_time,
      params_.rss_params.safety_margin, params_.rss_params.min_vel_th, debug_data_.target_polygons,
      colliding_object);
  });

  if (collision_point) debug_data_.colliding_object = colliding_object;

  return collision_point;
}

void filter_objects(PredictedObjects & objects)
{
  objects.objects.erase(
    std::remove_if(
      objects.objects.begin(), objects.objects.end(),
      [&](const auto & object) {
        if (object.kinematics.initial_twist_with_covariance.twist.linear.x > max_velocity_th_)
          return true;
        const auto & label = object.classification.empty() ? ObjectClassification::UNKNOWN
                                                           : object.classification.front().label;
        if (classification_to_object_type.count(label) == 0) return true;
        return object_types_.count(classification_to_object_type.at(label)) == 0;
      }),
    objects.objects.end());
}

void ObstacleTracker::update_objects(
  const PredictedObjects & objects, PredictedObjects & persistent_objects, const rclcpp::Time & now)
{
  for (auto it = persistent_objects_map_.begin(); it != persistent_objects_map_.end();) {
    const auto idle_time = (now - it->second.last_seen_time).seconds();
    const bool is_erase =
      !it->second.is_active ? idle_time > grace_period_ : idle_time > off_time_buffer_;
    if (is_erase)
      it = persistent_objects_map_.erase(it);
    else
      it++;
  }

  auto closest_object_uuid =
    [&](const PredictedObject & object) -> std::optional<boost::uuids::uuid> {
    std::optional<boost::uuids::uuid> closest_uuid = std::nullopt;
    if (persistent_objects_map_.empty()) return std::nullopt;
    double min_distance = std::numeric_limits<double>::max();
    double yaw_diff = std::numeric_limits<double>::max();
    for (const auto & [uuid, existing_object] : persistent_objects_map_) {
      const auto existing_obj_label = existing_object.object.classification.empty()
                                        ? ObjectClassification::UNKNOWN
                                        : existing_object.object.classification.front().label;
      const auto obj_label = object.classification.empty() ? ObjectClassification::UNKNOWN
                                                           : object.classification.front().label;
      if (existing_obj_label != obj_label) continue;
      const auto distance = autoware_utils::calc_distance2d(
        object.kinematics.initial_pose_with_covariance.pose.position,
        existing_object.object.kinematics.initial_pose_with_covariance.pose.position);
      if (distance < min_distance) {
        min_distance = distance;
        closest_uuid = uuid;
        yaw_diff = std::abs(
          autoware_utils_geometry::calc_yaw_deviation(
            object.kinematics.initial_pose_with_covariance.pose,
            existing_object.object.kinematics.initial_pose_with_covariance.pose));
      }
    }
    if (closest_uuid && (min_distance > object_distance_th_ || yaw_diff > object_yaw_th_)) {
      closest_uuid = std::nullopt;
    }
    return closest_uuid;
  };

  for (const auto & object : objects.objects) {
    const auto closest_uuid = closest_object_uuid(object);
    if (!closest_uuid) {
      persistent_objects_map_.emplace(id_generator_(), PersistentObject(object, now));
      continue;
    }
    auto & closest_object = persistent_objects_map_.at(closest_uuid.value());
    closest_object.last_seen_time = now;
    closest_object.object = object;
    const auto duration = (now - closest_object.first_seen_time).seconds();
    closest_object.is_active = duration >= on_time_buffer_;
  }

  for (const auto & [uuid, entry] : persistent_objects_map_) {
    if (entry.is_active) {
      persistent_objects.objects.push_back(entry.object);
    }
  }
}

double calc_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  return std::hypot(p1.x - p2.x, p1.y - p2.y);
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

std::optional<CollisionPoint> get_nearest_object_collision(
  const TrajectoryPoints & trajectory_points, const TrajectoryShape & trajectory_shape,
  const PredictedObjects & objects, MultiPolygon2d & target_polygons,
  PredictedObject & colliding_object)
{
  if (objects.objects.empty()) return std::nullopt;

  auto min_arc_length = std::numeric_limits<double>::max();
  geometry_msgs::msg::Point nearest_collision_point;
  bool found_collision = false;
  for (const auto & object : objects.objects) {
    const auto object_pose = object.kinematics.initial_pose_with_covariance.pose;
    const auto object_polygon = autoware_utils::to_polygon2d(object_pose, object.shape);
    if (boost::geometry::disjoint(object_polygon, trajectory_shape.polygon)) {
      continue;
    }
    found_collision = true;
    for (const auto & point : object_polygon.outer()) {
      geometry_msgs::msg::Point p = geometry_msgs::msg::Point().set__x(point.x()).set__y(point.y());
      auto arc_length = motion_utils::calcSignedArcLength(trajectory_points, 0, p);
      if (arc_length < min_arc_length) {
        min_arc_length = arc_length;
        nearest_collision_point = p;
        colliding_object = object;
      }
    }
    target_polygons.emplace_back(object_polygon);
  }

  if (!found_collision) return std::nullopt;
  return CollisionPoint(nearest_collision_point, min_arc_length);
}

Polygon2d to_polygon2d(
  const geometry_msgs::msg::Pose & pose, const autoware_perception_msgs::msg::Shape & shape)
{
  Polygon2d polygon;

  if (shape.type == autoware_perception_msgs::msg::Shape::BOUNDING_BOX) {
    const auto point0 = autoware_utils_geometry::calc_offset_pose(
                          pose, shape.dimensions.x / 2.0, shape.dimensions.y / 2.0, 0.0)
                          .position;
    const auto point1 = autoware_utils_geometry::calc_offset_pose(
                          pose, -shape.dimensions.x / 2.0, shape.dimensions.y / 2.0, 0.0)
                          .position;
    const auto point2 = autoware_utils_geometry::calc_offset_pose(
                          pose, -shape.dimensions.x / 2.0, -shape.dimensions.y / 2.0, 0.0)
                          .position;
    const auto point3 = autoware_utils_geometry::calc_offset_pose(
                          pose, shape.dimensions.x / 2.0, -shape.dimensions.y / 2.0, 0.0)
                          .position;

    append_point_to_polygon(polygon, point0);
    append_point_to_polygon(polygon, point1);
    append_point_to_polygon(polygon, point2);
    append_point_to_polygon(polygon, point3);
  } else if (shape.type == autoware_perception_msgs::msg::Shape::CYLINDER) {
    const double radius = shape.dimensions.x / 2.0;
    constexpr int circle_discrete_num = 6;
    for (int i = 0; i < circle_discrete_num; ++i) {
      geometry_msgs::msg::Point point;
      point.x = std::cos(
                  (static_cast<double>(i) / static_cast<double>(circle_discrete_num)) * 2.0 * M_PI +
                  M_PI / static_cast<double>(circle_discrete_num)) *
                  radius +
                pose.position.x;
      point.y = std::sin(
                  (static_cast<double>(i) / static_cast<double>(circle_discrete_num)) * 2.0 * M_PI +
                  M_PI / static_cast<double>(circle_discrete_num)) *
                  radius +
                pose.position.y;
      append_point_to_polygon(polygon, point);
    }
  } else if (shape.type == autoware_perception_msgs::msg::Shape::POLYGON) {
    const double poly_yaw = tf2::getYaw(pose.orientation);
    const auto rotated_footprint = rotate_polygon(shape.footprint, poly_yaw);
    for (const auto rel_point : rotated_footprint.points) {
      geometry_msgs::msg::Point abs_point;
      abs_point.x = pose.position.x + rel_point.x;
      abs_point.y = pose.position.y + rel_point.y;

      append_point_to_polygon(polygon, abs_point);
    }
  } else {
    throw std::logic_error("The shape type is not supported in autoware_utils.");
  }

  // NOTE: push back the first point in order to close polygon
  if (!polygon.outer().empty()) {
    append_point_to_polygon(polygon, polygon.outer().front());
  }

  return is_clockwise(polygon) ? polygon : inverse_clockwise(polygon);
}

  using autoware_utils_geometry::calc_offset_pose;
  Polygon2d polygon;
  const auto point0 = calc_offset_pose(base_link_pose, base_to_front, width / 2.0, 0.0).position;
  const auto point1 = calc_offset_pose(base_link_pose, base_to_front, -width / 2.0, 0.0).position;
  const auto point2 = calc_offset_pose(base_link_pose, -base_to_rear, -width / 2.0, 0.0).position;
  const auto point3 = calc_offset_pose(base_link_pose, -base_to_rear, width / 2.0, 0.0).position;

  append_point_to_polygon(polygon, point0);
  append_point_to_polygon(polygon, point1);
  append_point_to_polygon(polygon, point2);
  append_point_to_polygon(polygon, point3);
  append_point_to_polygon(polygon, point0);

  return is_clockwise(polygon) ? polygon : inverse_clockwise(polygon);
}

double get_area(const autoware_perception_msgs::msg::Shape & shape)
{
  if (shape.type == autoware_perception_msgs::msg::Shape::BOUNDING_BOX) {
    return get_rectangle_area(shape.dimensions);
  } else if (shape.type == autoware_perception_msgs::msg::Shape::CYLINDER) {
    return get_circle_area(shape.dimensions);
  } else if (shape.type == autoware_perception_msgs::msg::Shape::POLYGON) {
    return get_polygon_area(shape.footprint);
  }

  throw std::logic_error("The shape type is not supported in autoware_utils.");
}

void append_point_to_polygon(Polygon2d & polygon, const geometry_msgs::msg::Point & geom_point)
{
  Point2d point;
  point.x() = geom_point.x;
  point.y() = geom_point.y;

  bg::append(polygon.outer(), point);
}

geometry_msgs::msg::Polygon rotate_polygon(
  const geometry_msgs::msg::Polygon & polygon, const double & angle)
{
  const double cos = std::cos(angle);
  const double sin = std::sin(angle);
  geometry_msgs::msg::Polygon rotated_polygon;
  for (const auto & point : polygon.points) {
    auto rotated_point = point;
    rotated_point.x = cos * point.x - sin * point.y;
    rotated_point.y = sin * point.x + cos * point.y;
    rotated_polygon.points.push_back(rotated_point);
  }
  return rotated_polygon;
}

bool is_clockwise(const Polygon2d & polygon)
{
  const int n = polygon.outer().size();
  const double x_offset = polygon.outer().at(0).x();
  const double y_offset = polygon.outer().at(0).y();
  double sum = 0.0;
  for (std::size_t i = 0; i < polygon.outer().size(); ++i) {
    sum +=
      (polygon.outer().at(i).x() - x_offset) * (polygon.outer().at((i + 1) % n).y() - y_offset) -
      (polygon.outer().at(i).y() - y_offset) * (polygon.outer().at((i + 1) % n).x() - x_offset);
  }

  return sum < 0.0;
}

Polygon2d inverse_clockwise(const Polygon2d & polygon)
{
  auto output_polygon = polygon;
  boost::geometry::reverse(output_polygon);
  return output_polygon;
}

double calcSignedArcLength(
  const T & points, const size_t src_idx, const geometry_msgs::msg::Point & dst_point)
{
  try {
    validateNonEmpty(points);
  } catch (const std::exception & e) {
    RCLCPP_DEBUG(get_logger(), "%s", e.what());
    return 0.0;
  }

  return -calcSignedArcLength(points, dst_point, src_idx);
}

double calcSignedArcLength(const T & points, const size_t src_idx, const size_t dst_idx)
{
  try {
    validateNonEmpty(points);
  } catch (const std::exception & e) {
    RCLCPP_DEBUG(get_logger(), "%s", e.what());
    return 0.0;
  }

  if (src_idx > dst_idx) {
    return -calcSignedArcLength(points, dst_idx, src_idx);
  }

  double dist_sum = 0.0;
  for (size_t i = src_idx; i < dst_idx; ++i) {
    dist_sum += autoware_utils_geometry::calc_distance2d(points.at(i), points.at(i + 1));
  }
  return dist_sum;
}

double calc_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  return std::hypot(p1.x - p2.x, p1.y - p2.y);
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

std::optional<CollisionPoint> ObstacleStop::check_pointcloud(const TrajectoryPoints & traj_points)
{
  autoware_utils_debug::ScopedTimeTrack st("ObstacleStop::check_pointcloud", *get_time_keeper());
  if (
    !params_.use_pointcloud || !data_->obstacle_pointcloud ||
    data_->obstacle_pointcloud->data.empty()) {
    return std::nullopt;
  }

  PointCloud::Ptr filtered_pointcloud(new PointCloud);
  pcl::fromROSMsg(*data_->obstacle_pointcloud, *filtered_pointcloud);
  {
    autoware_utils_debug::ScopedTimeTrack stt(
      "ObstacleStop::filter_pointcloud", *get_time_keeper());
    const auto & bounding_box = debug_data_.trajectory_shape.bounding_box;
    const auto rel_min_corner = autoware_utils_geometry::inverse_transform_point(
      bounding_box.min_corner().to_3d(), data_->current_odometry->pose.pose);
    const auto rel_max_corner = autoware_utils_geometry::inverse_transform_point(
      bounding_box.max_corner().to_3d(), data_->current_odometry->pose.pose);
    constexpr double buffer = 1.0;
    const auto [min_x, max_x] = std::minmax(rel_min_corner.x(), rel_max_corner.x());
    const auto [min_y, max_y] = std::minmax(rel_min_corner.y(), rel_max_corner.y());
    const auto min_z = params_.pointcloud.min_height;
    const auto max_z = data_->vehicle_info.vehicle_height_m + params_.pointcloud.height_buffer;
    pointcloud_filter_->filter_pointcloud(
      filtered_pointcloud, min_x - buffer, max_x + buffer, min_y - buffer, max_y + buffer, min_z,
      max_z);
  }

  PointCloud::Ptr clustered_points(new PointCloud);
  {
    autoware_utils_debug::ScopedTimeTrack stt(
      "ObstacleStop::cluster_pointcloud", *get_time_keeper());
    pointcloud_filter_->cluster_pointcloud(
      filtered_pointcloud, clustered_points, params_.pointcloud.clustering.min_height);
  }

  if (!clustered_points->empty()) {
    geometry_msgs::msg::TransformStamped transform_stamped;
    try {
      transform_stamped = data_->tf_buffer.lookupTransform(
        "map", data_->obstacle_pointcloud->header.frame_id, tf2::TimePointZero);
    } catch (tf2::TransformException & e) {
      RCLCPP_WARN(get_node_ptr()->get_logger(), "no transform found for pointcloud: %s", e.what());
      return std::nullopt;
    }

    Eigen::Affine3f isometry = tf2::transformToEigen(transform_stamped.transform).cast<float>();
    autoware_utils::transform_pointcloud(*clustered_points, *clustered_points, isometry);
  }

  {
    const auto cluster_pointcloud = std::make_shared<sensor_msgs::msg::PointCloud2>();
    pcl::toROSMsg(*clustered_points, *cluster_pointcloud);
    cluster_pointcloud->header.stamp = data_->obstacle_pointcloud->header.stamp;
    cluster_pointcloud->header.frame_id = "map";
    debug_data_.cluster_points = cluster_pointcloud;
  }

  if (data_->predicted_objects && !data_->predicted_objects->objects.empty()) {
    autoware_utils_debug::ScopedTimeTrack stt(
      "ObstacleStop::filter_pointcloud_by_object", *get_time_keeper());
    pointcloud_filter_->filter_pointcloud_by_object(clustered_points, *data_->predicted_objects);
  }

  PointCloud::Ptr active_points(new PointCloud);
  obstacle_tracker_->update_points(clustered_points, active_points, get_clock()->now());

  std::optional<CollisionPoint> collision_point;
  {
    autoware_utils_debug::ScopedTimeTrack stt(
      "ObstacleStop::get_nearest_pcd_collision", *get_time_keeper());
    collision_point = get_nearest_pcd_collision(
      traj_points, debug_data_.trajectory_shape, active_points, debug_data_.target_pcd_points);
  }

  return collision_point;
}

void PointCloudFilter::filter_pointcloud(
  PointCloud::Ptr & pointcloud, const double min_x, const double max_x, const double min_y,
  const double max_y, const double min_z, const double max_z)
{
  if (pointcloud->empty()) return;

  crop_box_.setMin(Eigen::Vector4f(min_x, min_y, min_z, 1.0));
  crop_box_.setMax(Eigen::Vector4f(max_x, max_y, max_z, 1.0));
  crop_box_.setInputCloud(pointcloud);
  crop_box_.filter(*pointcloud);

  if (pointcloud->empty()) return;

  voxel_grid_.setInputCloud(pointcloud);
  voxel_grid_.filter(*pointcloud);
}

filter (PointCloud &output)
{
  if (!initCompute ())
    return;

  if (input_.get () == &output)  // cloud_in = cloud_out
  {
    PointCloud output_temp;
    applyFilter (output_temp);
    output_temp.header = input_->header;
    output_temp.sensor_origin_ = input_->sensor_origin_;
    output_temp.sensor_orientation_ = input_->sensor_orientation_;
    pcl::copyPointCloud (output_temp, output);
  }
  else
  {
    output.header = input_->header;
    output.sensor_origin_ = input_->sensor_origin_;
    output.sensor_orientation_ = input_->sensor_orientation_;
    applyFilter (output);
  }

  deinitCompute ();
}

