std::optional<CollisionPoint> get_nearest_pcd_collision(
  const TrajectoryPoints & trajectory_points, const TrajectoryShape & trajectory_shape,
  const PointCloud::Ptr & pointcloud, std::vector<geometry_msgs::msg::Point> & target_pcd_points)
{
  if (pointcloud->empty()) return std::nullopt;

  PointCloud::Ptr pointcloud_in_polygon(new PointCloud);
  for (const auto & point : *pointcloud) {
    if (boost::geometry::within(
          autoware_utils::Point2d{point.x, point.y}, trajectory_shape.polygon)) {
      pointcloud_in_polygon->push_back(point);
    }
  }

  if (pointcloud_in_polygon->empty()) return std::nullopt;

  auto min_arc_length = std::numeric_limits<double>::max();
  geometry_msgs::msg::Point nearest_collision_point;
  for (const auto & point : *pointcloud_in_polygon) {
    geometry_msgs::msg::Point p =
      geometry_msgs::msg::Point().set__x(point.x).set__y(point.y).set__z(point.z);
    auto arc_length = motion_utils::calcSignedArcLength(trajectory_points, 0, p);
    if (arc_length < min_arc_length) {
      min_arc_length = arc_length;
      nearest_collision_point = p;
    }
    target_pcd_points.emplace_back(p);
  }

  return CollisionPoint(nearest_collision_point, min_arc_length);
}

double calcSignedArcLength(
  const T & points, const size_t src_idx, const geometry_msgs::msg::Point & dst_point)
{
  try {
    validateNonEmpty(points);
  } catch (const std::exception & e) {
    RCLCPP_DEBUG(get_logger(), "%s", e.what());
    return 0.0;
  }

  return -calcSignedArcLength(points, dst_point, src_idx);
}

double calcSignedArcLength(const T & points, const size_t src_idx, const size_t dst_idx)
{
  try {
    validateNonEmpty(points);
  } catch (const std::exception & e) {
    RCLCPP_DEBUG(get_logger(), "%s", e.what());
    return 0.0;
  }

  if (src_idx > dst_idx) {
    return -calcSignedArcLength(points, dst_idx, src_idx);
  }

  double dist_sum = 0.0;
  for (size_t i = src_idx; i < dst_idx; ++i) {
    dist_sum += autoware_utils_geometry::calc_distance2d(points.at(i), points.at(i + 1));
  }
  return dist_sum;
}

double calc_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  return std::hypot(p1.x - p2.x, p1.y - p2.y);
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

bool ObstacleStop::set_stop_point(TrajectoryPoints & traj_points)
{
  autoware_utils_debug::ScopedTimeTrack st("ObstacleStop::set_stop_point", *get_time_keeper());
  const auto target_stop_point_arc_length = std::invoke([&]() -> double {
    const auto stop_margin = params_.stop_margin + data_->vehicle_info.max_longitudinal_offset_m;
    auto min_stopping_distance = motion_utils::calculate_stop_distance(
      data_->current_odometry->twist.twist.linear.x,
      data_->current_acceleration->accel.accel.linear.x, params_.maximum_stopping_decel,
      params_.stopping_jerk, 0.0);
    if (!min_stopping_distance) min_stopping_distance = 0.0;
    return std::clamp(
      nearest_collision_point_->arc_length - stop_margin, min_stopping_distance.value(),
      debug_data_.trajectory_shape.trajectory_length);
  });

  auto skip = [&](const std::string & msg) {
    RCLCPP_WARN_THROTTLE(
      get_node_ptr()->get_logger(), *get_clock(), 1000,
      "[TM ObstacleStop] %s, skip inserting stop point", msg.c_str());
    return false;
  };

  constexpr double zero_velocity_threshold = 0.01;
  auto checked_distance = 0.0;
  for (size_t i = 1; i < traj_points.size(); ++i) {
    const auto & curr = traj_points.at(i);
    const auto & prev = traj_points.at(i - 1);
    checked_distance +=
      autoware_utils_geometry::calc_distance2d(curr.pose.position, prev.pose.position);
    if (curr.longitudinal_velocity_mps > zero_velocity_threshold) continue;
    if (checked_distance < target_stop_point_arc_length) {
      return skip("Preceding stop point exists");
    }
  }

  if (
    target_stop_point_arc_length < params_.arrived_distance_threshold ||
    !apply_stopping(traj_points, target_stop_point_arc_length)) {
    traj_points = std::invoke([&]() {
      TrajectoryPoints stop_points;
      auto p = traj_points.front();
      p.longitudinal_velocity_mps = 0.0;
      p.acceleration_mps2 = 0.0;
      p.time_from_start = rclcpp::Duration::from_seconds(0.0);
      stop_points.push_back(p);
      p.time_from_start = rclcpp::Duration::from_seconds(trajectory_time_step_);
      stop_points.push_back(p);
      return stop_points;
    });
  }

  const auto & stop_pose = traj_points.back().pose;
  const auto & ego_pose = data_->current_odometry->pose.pose;
  planning_factor_interface_->add(
    traj_points, ego_pose, stop_pose, PlanningFactor::STOP, safety_factors_);

  RCLCPP_WARN_THROTTLE(
    get_node_ptr()->get_logger(), *get_clock(), 1000,
    "[TM ObstacleStop] Inserted stop point at arc length %f m", target_stop_point_arc_length);
  return true;
}

[[nodiscard]] std::optional<double> calculate_stop_distance(
  const double v0, const double a0, const double decel_limit, const double jerk_limit,
  const double initial_time_delay)
{
  // already stopped or reversing
  if (v0 <= 0.0) {
    return 0.0;
  }

  // jerk and acceleration limits must be strictly negative to stop a forward-moving vehicle.
  const auto negative_jerk_limit = -std::abs(jerk_limit);
  // ensure current_acc respects the deceleration limit, otherwise the maths break down
  const auto negative_decel_limit = std::min(-std::abs(decel_limit), a0);
  // using epsilon to prevent division by zero.
  if (negative_jerk_limit >= -epsilon || negative_decel_limit >= -epsilon) {
    return std::nullopt;
  }

  // Phase 1: latency delay
  const double t1 = std::max(0.0, initial_time_delay);
  const auto [x1, v1, a1] = update(0.0, v0, a0, 0.0, t1);

  // If the vehicle naturally stops during the delay phase due to existing deceleration
  if (v1 <= 0.0 && (a0 <= -epsilon || a0 >= epsilon)) {
    const double t_stop = -v0 / a0;
    const auto [x_stop, v_stop, a_stop] = update(0.0, v0, a0, 0.0, t_stop);
    return std::max(0.0, x_stop);
  }

  // Phase 2: jerk-limited braking
  // Calculate what the velocity (v2) would be exactly when the acceleration reaches acc_limit
  const double v2 =
    v1 + (negative_decel_limit * negative_decel_limit - a1 * a1) / (2.0 * negative_jerk_limit);

  if (v2 <= 0.0) {
    // The vehicle reaches v = 0 before hitting the maximum deceleration limit.
    // Solve for t where 0 = v1 + a1*t + 0.5*j*t^2
    const double discriminant = a1 * a1 - 2.0 * negative_jerk_limit * v1;

    // should be impossible
    if (discriminant < 0.0) {
      return std::nullopt;
    }

    const double t2 = std::max(0.0, -(a1 + std::sqrt(discriminant)) / negative_jerk_limit);
    const auto [x_stop, v_stop, a_stop] = update(x1, v1, a1, negative_jerk_limit, t2);

    return std::max(0.0, x_stop);
  }

  // The vehicle successfully reaches the maximum deceleration limit.
  const double t2 = std::max(0.0, (negative_decel_limit - a1) / negative_jerk_limit);
  const auto [x2, v2_final, a2_final] = update(x1, v1, a1, negative_jerk_limit, t2);

  // Phase 3: Constant maximum deceleration
  // Decelerate at acc_limit from v2_final down to 0.
  const double x3 = -(v2_final * v2_final) / (2.0 * negative_decel_limit);

  return std::max(0.0, x2 + x3);
}

double calc_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  return std::hypot(p1.x - p2.x, p1.y - p2.y);
}

geometry_msgs::msg::Point get_point(const T & p)
{
