bool ObstacleStop::apply_stopping(
  TrajectoryPoints & traj_points, const double target_stop_point_arc_length) const
{
  if (target_stop_point_arc_length < 1e-3) return false;

  auto trajectory = traj_points;

  const auto stop_index = insert_stop_point(
    trajectory, target_stop_point_arc_length, debug_data_.trajectory_shape.trajectory_length);

  trajectory.erase(trajectory.begin() + stop_index + 1, trajectory.end());
  trajectory.back().longitudinal_velocity_mps = 0.0;
  trajectory.back().acceleration_mps2 = 0.0;

  constexpr double min_v_ref = 1.0;
  const auto v_ref = std::max<double>(min_v_ref, trajectory.front().longitudinal_velocity_mps);
  const auto required_decel = std::abs(v_ref * v_ref / (2.0 * target_stop_point_arc_length));
  const auto jerk = std::abs(params_.stopping_jerk);
  const auto decel = std::clamp(
    required_decel, std::abs(params_.nominal_stopping_decel),
    std::abs(params_.maximum_stopping_decel));

  const auto vel_update_start_index = update_velocities(trajectory, jerk, decel);
  const auto interpolate_start_index = vel_update_start_index > 0 ? vel_update_start_index - 1 : 0;

  auto trajectory_interpolation_util =
    InterpolationTrajectory::Builder{}
      .set_xy_interpolator<AkimaSpline>()  // Set interpolator for x-y plane
      .set_longitudinal_velocity_interpolator<AkimaSpline>()
      .build(trajectory);
  if (!trajectory_interpolation_util) {
    RCLCPP_WARN_THROTTLE(
      get_node_ptr()->get_logger(), *get_clock(), 1000,
      "[TM ObstacleStop] Failed to build interpolation trajectory");
    return false;
  }

  const auto dt = trajectory_time_step_;

  if (dt < 1e-3) {
    RCLCPP_ERROR_THROTTLE(
      get_node_ptr()->get_logger(), *get_clock(), 1000,
      "[TM ObstacleStop] Invalid trajectory time step: %f, unable to interpolate trajectory", dt);
    traj_points = std::move(trajectory);
    return true;
  }

  const auto s_max = trajectory_interpolation_util->length();
  const auto interpolate_start_arc_length =
    trajectory_interpolation_util->get_underlying_bases().at(interpolate_start_index);
  trajectory_interpolation_util->align_orientation_with_trajectory_direction();
  traj_points.erase(traj_points.begin() + interpolate_start_index + 1, traj_points.end());
  double s_curr{interpolate_start_arc_length};
  while (s_curr <= s_max) {
    const auto v_curr = traj_points.back().longitudinal_velocity_mps;
    const auto a_curr = traj_points.back().acceleration_mps2;
    const auto t_curr = rclcpp::Duration(traj_points.back().time_from_start);
    if (v_curr < 1e-3) break;

    double ds = v_curr * dt + 0.5 * a_curr * dt * dt;
    if (ds < 1e-3) break;

    s_curr += ds;
    const auto s_clamped = std::min(s_curr, s_max);

    auto p = trajectory_interpolation_util->compute(s_clamped);
    p.acceleration_mps2 = (p.longitudinal_velocity_mps - v_curr) / static_cast<float>(dt);
    p.time_from_start = t_curr + rclcpp::Duration::from_seconds(dt);
    traj_points.push_back(p);
  }

  return true;
}

size_t insert_stop_point(
  TrajectoryPoints & trajectory, const double target_stop_point_arc_length,
  const double traj_length)
{
  const auto index = motion_utils::insertStopPoint(target_stop_point_arc_length, trajectory);
  if (index) return index.value();

  // TODO(Quda): this is a temporary fix, need to check why insertStopPoint fails when target
  // distance is equal to trajectory length
  if (target_stop_point_arc_length < traj_length) {
    auto dist = 0.0;
    auto it = std::adjacent_find(
      trajectory.begin(), trajectory.end(), [&](const auto & p, const auto & next) {
        dist += autoware_utils_geometry::calc_distance2d(p.pose.position, next.pose.position);
        return dist >= target_stop_point_arc_length - 1e-3;
      });
    if (it != trajectory.end()) {
      it->longitudinal_velocity_mps = 0.0;
      it->acceleration_mps2 = 0.0;
      return std::distance(trajectory.begin(), it);
    }
  }

  trajectory.back().longitudinal_velocity_mps = 0.0;
  trajectory.back().acceleration_mps2 = 0.0;
  return trajectory.size() - 1;
}

std::optional<size_t> insertStopPoint(
  const double distance_to_stop_point, T & points_with_twist, const double overlap_threshold = 1e-3)
{
  validateNonEmpty(points_with_twist);

  if (distance_to_stop_point < 0.0) {
    return std::nullopt;
  }

  double accumulated_length = 0;
  for (size_t i = 0; i < points_with_twist.size() - 1; ++i) {
    const auto curr_pose = autoware_utils_geometry::get_pose(points_with_twist.at(i));
    const auto next_pose = autoware_utils_geometry::get_pose(points_with_twist.at(i + 1));
    const double length = autoware_utils_geometry::calc_distance2d(curr_pose, next_pose);
    if (accumulated_length + length + overlap_threshold > distance_to_stop_point) {
      const double insert_length = distance_to_stop_point - accumulated_length;
      return insertStopPoint(i, insert_length, points_with_twist, overlap_threshold);
    }
    accumulated_length += length;
  }

  return std::nullopt;
}

double calc_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  return std::hypot(p1.x - p2.x, p1.y - p2.y);
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

std::optional<size_t> insertStopPoint(
  const size_t src_segment_idx, const double distance_to_stop_point, T & points_with_twist,
  const double overlap_threshold = 1e-3)
{
  validateNonEmpty(points_with_twist);

  if (distance_to_stop_point < 0.0 || src_segment_idx >= points_with_twist.size() - 1) {
    return std::nullopt;
  }

  const auto stop_idx = insertTargetPoint(
    src_segment_idx, distance_to_stop_point, points_with_twist, overlap_threshold);
  if (!stop_idx) {
    return std::nullopt;
  }

  for (size_t i = *stop_idx; i < points_with_twist.size(); ++i) {
    autoware_utils_geometry::set_longitudinal_velocity(0.0, points_with_twist.at(i));
  }

  return stop_idx;
}

std::optional<size_t> insertTargetPoint(
  const size_t seg_idx, const geometry_msgs::msg::Point & p_target, T & points,
  const double overlap_threshold = 1e-3)
{
  try {
    validateNonEmpty(points);
  } catch (const std::exception & e) {
    RCLCPP_DEBUG(get_logger(), "%s", e.what());
    return {};
  }

  // invalid segment index
  if (seg_idx + 1 >= points.size()) {
    return {};
  }

  const auto p_front = autoware_utils_geometry::get_point(points.at(seg_idx));
  const auto p_back = autoware_utils_geometry::get_point(points.at(seg_idx + 1));

  try {
    validateNonSharpAngle(p_front, p_target, p_back);
  } catch (const std::exception & e) {
    RCLCPP_DEBUG(get_logger(), "%s", e.what());
    return {};
  }

  const auto overlap_with_front =
    autoware_utils_geometry::calc_distance2d(p_target, p_front) < overlap_threshold;
  const auto overlap_with_back =
    autoware_utils_geometry::calc_distance2d(p_target, p_back) < overlap_threshold;

  const auto is_driving_forward = isDrivingForward(points);
  if (!is_driving_forward) {
    return {};
  }

  geometry_msgs::msg::Pose target_pose;
  {
    const auto p_base = is_driving_forward.value() ? p_back : p_front;
    const auto pitch = autoware_utils_geometry::calc_elevation_angle(p_target, p_base);
    const auto yaw = autoware_utils_geometry::calc_azimuth_angle(p_target, p_base);

    target_pose.position = p_target;
    target_pose.orientation = autoware_utils_geometry::create_quaternion_from_rpy(0.0, pitch, yaw);
  }

  auto p_insert = points.at(seg_idx);
  autoware_utils_geometry::set_pose(target_pose, p_insert);

  geometry_msgs::msg::Pose base_pose;
  {
    const auto p_base = is_driving_forward.value() ? p_front : p_back;
    const auto pitch = autoware_utils_geometry::calc_elevation_angle(p_base, p_target);
    const auto yaw = autoware_utils_geometry::calc_azimuth_angle(p_base, p_target);

    base_pose.position = autoware_utils_geometry::get_point(p_base);
    base_pose.orientation = autoware_utils_geometry::create_quaternion_from_rpy(0.0, pitch, yaw);
  }

  if (!overlap_with_front && !overlap_with_back) {
    if (is_driving_forward.value()) {
      autoware_utils_geometry::set_pose(base_pose, points.at(seg_idx));
    } else {
      autoware_utils_geometry::set_pose(base_pose, points.at(seg_idx + 1));
    }
    points.insert(points.begin() + seg_idx + 1, p_insert);
    return seg_idx + 1;
  }

  if (overlap_with_back) {
    return seg_idx + 1;
  }

  return seg_idx;
}

void validateNonSharpAngle(
  const T & point1, const T & point2, const T & point3,
  const double angle_threshold = autoware_utils_math::pi / 4)
{
  const auto p1 = autoware_utils_geometry::get_point(point1);
  const auto p2 = autoware_utils_geometry::get_point(point2);
  const auto p3 = autoware_utils_geometry::get_point(point3);

  const std::vector vec_1to2 = {p2.x - p1.x, p2.y - p1.y, p2.z - p1.z};
  const std::vector vec_3to2 = {p2.x - p3.x, p2.y - p3.y, p2.z - p3.z};
  const auto product = std::inner_product(vec_1to2.begin(), vec_1to2.end(), vec_3to2.begin(), 0.0);

  const auto dist_1to2 = autoware_utils_geometry::calc_distance3d(p1, p2);
  const auto dist_3to2 = autoware_utils_geometry::calc_distance3d(p3, p2);

  constexpr double epsilon = 1e-3;
  if (std::cos(angle_threshold) < product / dist_1to2 / dist_3to2 + epsilon) {
    autoware_utils_system::print_backtrace();
    throw std::invalid_argument(
      "[autoware_motion_utils] validateNonSharpAngle(): Too sharp angle.");
  }
}

